const trades = $json.result;

const context = trades.slice(0,5).map((t,i) => {
  const p = t.payload;

  return `Trade ${i+1}
strategy: ${p.strategy}
position: ${p.position_side}
trend: ${p.trend_direction}
volatility: ${p.volatility_category}
pressure: ${p.market_pressure_state}
rsi: ${p.rsi_state}
result: ${p.result || "open"}
score: ${t.score}`;
}).join("\n\n");

return [{
  json: {
    query: $node["Query Qdrant"].json.query_text,
    context: context
  }
}];

const query = $json.query;
const context = $json.context;

const prompt = `
You are evaluating vector retrieval quality for a crypto trade retrieval system.

Query:
${query}

Retrieved trades:
${context}

Evaluation Instructions:
Evaluate how well the retrieved trades match the query based on:

- sentiment structure
- RSI state
- trend direction
- volatility category
- market pressure state
- strategy similarity
- regime similarity

Scoring Rules:
- 1.0 = highly relevant matches across most attributes
- 0.5 = partially relevant with mixed alignment
- 0.0 = weak or irrelevant retrievals

Return ONLY valid JSON.

{
  "metric": "relevance",
  "score": 0-1,
  "comment": "one short sentence"
}
`;

return [{
  json: {
    prompt
  }
}];

const query = $json.query;
const context = $json.context;

const prompt = `
You evaluate retrieval recall for a crypto trade vector retrieval system.

Query:
${query}

Retrieved trades:
${context}

Task:
Determine whether the retrieval results likely captured MOST of the relevant trades that match the query conditions.

Evaluate recall based on:
- sentiment structure
- RSI state
- trend direction
- volatility category
- market pressure state
- strategy similarity
- regime similarity

High recall means:
Most relevant trades that should match the query are present in the retrieved results.

Low recall means:
Important relevant trades are likely missing from the retrieved results.

Focus on whether the retrieval appears comprehensive enough, not just accurate.

Return ONLY valid JSON.

{
 "metric": "recall",
 "score": 0-1,
 "comment": "one short sentence"
}
`;

return [{
  json: {
    prompt
  }
}];

