const context = $json.context;

const prompt = `
You evaluate retrieval precision for a crypto trade retrieval system.

Query:
${query}

Retrieved trades:
${context}

Task:
Determine whether the retrieved trades actually contain the semantic and technical features described in the query.

Evaluate similarity based on:
- sentiment structure
- RSI state
- trend direction
- volatility category
- market pressure state
- strategy similarity
- regime similarity

High precision means:
Most retrieved trades strongly match the requested conditions.

Low precision means:
Many retrieved trades are only partially related or contain mismatched attributes.

Return ONLY valid JSON.

{
 "metric": "precision",
 "score": 0-1,
 "comment": "one short sentence"
}
`;

return [{
  json: {
    prompt
  }
}];

const query = $json.query;
const context = $json.context;

const prompt = `
You evaluate faithfulness for a crypto trade retrieval evaluation system.

Query:
${query}

Retrieved trades:
${context}

Task:
Determine whether conclusions and reasoning about the retrieved trades can be directly supported by the visible retrieved data.

Evaluate whether the analysis stays grounded in:
- sentiment structure
- RSI state
- trend direction
- volatility category
- market pressure state
- strategy information
- regime labels
- visible retrieval scores

High faithfulness means:
All conclusions are directly supported by the retrieved trade information.

Low faithfulness means:
The analysis assumes missing information, invents unsupported conclusions, or relies on attributes not visible in the retrieved trades.

Do NOT reward speculation.

Return ONLY valid JSON.

{
 "metric": "faithfulness",
 "score": 0-1,
 "comment": "one short sentence"
}
`;

return [{
  json: {
    prompt
  }
}];

const query = $json.query;
const context = $json.context;

const prompt = `
You evaluate response relevance for a crypto trade retrieval evaluation system.

Query:
${query}

Retrieved trades:
${context}

Task:
Determine whether the retrieved trades and resulting analysis would directly answer the user's query.

Evaluate whether the retrieval addresses:
- sentiment structure
- RSI state
- trend direction
- volatility category
- market pressure state
- strategy similarity
- regime similarity
- requested semantic conditions

High response relevance means:
The retrieved trades and resulting explanation directly address the user's requested conditions and retrieval intent.

Low response relevance means:
The response focuses on unrelated attributes, weakly related trades, or misses the core intent of the query.

Focus on whether the retrieval meaningfully answers the user's request, not just whether trades were retrieved.

Return ONLY valid JSON.

{
 "metric": "response_relevance",
 "score": 0-1,
 "comment": "one short sentence"
}
`;

return [{
  json: {
    prompt
  }
}];

