const itemsArr = items;

// basis info
const result = {
  Query_Text: itemsArr[0].json.query,
  Context: itemsArr[0].json.context,
  Pair: itemsArr[0].json.pair,
  Top_k: itemsArr[0].json.top_k,

  // metrics
  Relevance: null,
  Faithfulness: null,
  Answer_Relevancy: null,
  Context_Precision: null,
  Context_Recall: null,
  Harmfulness: 0
};

// loop door alle metric items
for (const item of itemsArr) {
  const metric = item.json.metric;
  const score = parseFloat(item.json.score);

  if (metric === "relevance") {
    result.Relevance = score;
  }

  if (metric === "faithfulness") {
    result.Faithfulness = score;
  }

  if (metric === "response_relevance") {
    result.Answer_Relevancy = score;
  }

  if (metric === "precision") {
    result.Context_Precision = score;
  }

  if (metric === "recall") {
    result.Context_Recall = score;
  }

  if (metric === "harmfulness") {
    result.Harmfulness = score;
  }
}

// return 1 rij
return [{ json: result }];
